def _runtime_pseudo_formal_block_routing_contract_scorecard_passed(
    payload: Mapping[str, Any],
) -> bool:
    count_keys = (
        "n_runtime_pseudo_formal_block_routing_rows",
        "n_runtime_pseudo_formal_block_routing_effective_rows",
        "n_runtime_pseudo_formal_block_routing_diagnostic_rows",
        "n_runtime_pseudo_formal_structural_decomposition_requests",
        "n_runtime_pseudo_formal_independent_block_verification_requests",
        "n_runtime_pseudo_formalization_required_formalization_manifests",
        "n_runtime_pseudo_formalization_required_missing_routing_rows",
        "n_runtime_pseudo_formal_block_routing_rows_missing_lane",
        "n_runtime_pseudo_formal_block_routing_rows_invalid_lane",
        "n_runtime_pseudo_formal_block_routing_rows_missing_work_order_id",
        "n_runtime_pseudo_formal_block_routing_rows_missing_source_block_id",
        "n_runtime_pseudo_formal_block_routing_rows_missing_source_anchors",
        "n_runtime_pseudo_formal_block_routing_rows_missing_target_identity",
        "n_runtime_pseudo_formal_block_routing_rows_missing_routing",
        "n_runtime_pseudo_formal_block_routing_rows_missing_queue_status",
        "n_runtime_pseudo_formal_block_routing_rows_missing_row_kind",
        "n_runtime_pseudo_formal_block_routing_rows_missing_method_lineage",
        "n_runtime_pseudo_formal_block_routing_rows_missing_scope_parent",
        "n_runtime_pseudo_formal_block_routing_rows_invalid_scope_parent",
        "n_runtime_pseudo_formal_block_routing_rows_missing_inherited_scope",
        "n_runtime_pseudo_formal_block_routing_rows_missing_or_wrong_nonproof_boundary",
        "n_runtime_pseudo_formal_block_routing_rows_missing_or_invalid_structural_quality",
        "n_runtime_pseudo_formal_block_routing_rows_missing_or_invalid_bv_quality",
    )
    telemetry_keys = (
        "runtime_pseudo_formal_block_routing_contract_complete",
        "runtime_pseudo_formal_block_routing_contract_issues",
        "runtime_pseudo_formal_block_routing_effective_target_lanes",
        "runtime_pseudo_formal_block_routing_diagnostic_target_lanes",
        "runtime_pseudo_formal_block_routing_row_kinds",
        "runtime_pseudo_formal_block_routing_diagnostic_row_kinds",
        "runtime_pseudo_formalization_required_manifest_ids",
        "runtime_pseudo_formalization_required_missing_routing_manifest_ids",
        "runtime_pseudo_formalization_routed_manifest_ids",
        "runtime_pseudo_formalization_effective_routed_manifest_ids",
        "n_runtime_pseudo_formalization_routed_manifests",
        "n_runtime_pseudo_formalization_effective_routed_manifests",
        *count_keys,
    )
    if not any(key in payload for key in telemetry_keys):
        return True
    if payload.get("runtime_pseudo_formal_block_routing_contract_complete") is not True:
        return False
    if not _scorecard_telemetry_keys_present(payload, count_keys):
        return False
    if not _scorecard_issue_list_empty(
        payload,
        "runtime_pseudo_formal_block_routing_contract_issues",
    ):
        return False
    if _safe_int(payload.get("n_runtime_pseudo_formal_block_routing_rows")) != (
        _safe_int(payload.get("n_runtime_pseudo_formal_block_routing_effective_rows"))
        + _safe_int(payload.get("n_runtime_pseudo_formal_block_routing_diagnostic_rows"))
    ):
        return False
    if (
        _safe_int(payload.get("n_runtime_pseudo_formal_block_routing_rows")) > 0
        and not all(
            key in payload
            for key in (
                "runtime_pseudo_formal_block_routing_effective_target_lanes",
                "runtime_pseudo_formal_block_routing_diagnostic_target_lanes",
                "runtime_pseudo_formal_block_routing_row_kinds",
                "runtime_pseudo_formal_block_routing_diagnostic_row_kinds",
            )
        )
    ):
        return False
    required_manifests = _safe_int(
        payload.get("n_runtime_pseudo_formalization_required_formalization_manifests")
    )
    required_manifest_ids = _scorecard_string_set(
        payload.get("runtime_pseudo_formalization_required_manifest_ids")
    )
    manifest_required = (
        required_manifests > 0
        or bool(required_manifest_ids)
        or _safe_int(
            payload.get("n_runtime_pseudo_formalization_required_missing_routing_rows")
        )
        > 0
    )
    if manifest_required:
        manifest_keys = (
            "runtime_pseudo_formalization_required_manifest_ids",
            "runtime_pseudo_formalization_required_missing_routing_manifest_ids",
            "runtime_pseudo_formalization_routed_manifest_ids",
            "runtime_pseudo_formalization_effective_routed_manifest_ids",
            "n_runtime_pseudo_formalization_routed_manifests",
            "n_runtime_pseudo_formalization_effective_routed_manifests",
        )
        if not _scorecard_telemetry_keys_present(payload, manifest_keys):
            return False
        missing_manifest_ids = _scorecard_string_set(
            payload.get(
                "runtime_pseudo_formalization_required_missing_routing_manifest_ids"
            )
        )
        routed_manifest_ids = _scorecard_string_set(
            payload.get("runtime_pseudo_formalization_routed_manifest_ids")
        )
        effective_routed_manifest_ids = _scorecard_string_set(
            payload.get("runtime_pseudo_formalization_effective_routed_manifest_ids")
        )
        effective_routed_manifests = _safe_int(
            payload.get("n_runtime_pseudo_formalization_effective_routed_manifests")
        )
        routed_manifests = _safe_int(
            payload.get("n_runtime_pseudo_formalization_routed_manifests")
        )
        if missing_manifest_ids:
            return False
        if len(required_manifest_ids) != required_manifests:
            return False
        if routed_manifests != len(routed_manifest_ids):
            return False
        if effective_routed_manifests != len(effective_routed_manifest_ids):
            return False
        if not required_manifest_ids.issubset(effective_routed_manifest_ids):
            return False
        if not effective_routed_manifest_ids.issubset(routed_manifest_ids):
            return False
    return all(
        _safe_int(payload.get(key)) == 0
        for key in count_keys[6:]
    )


def _runtime_research_path_control_scorecard_passed(payload: Mapping[str, Any]) -> bool:
    if payload.get("runtime_research_path_control_propagated") is not True:
        return False
    if (
        payload.get("runtime_research_path_execution_summary_source")
        != "result_artifacts_recomputed"
    ):
        return False
    summary = payload.get("runtime_research_path_execution_summary", {})
    if not isinstance(summary, Mapping):
        return False
    n_current = _safe_int(summary.get("n_current_artifacts"))
    n_controlled = _safe_int(summary.get("n_controlled_artifacts"))
    n_with_contract = _safe_int(
        summary.get("n_controlled_artifacts_with_evidence_contract")
    )
    return bool(
        summary.get("path_control_propagated") is True
        and n_current > 0
        and n_current == n_controlled
        and n_controlled == n_with_contract
        and _safe_int(summary.get("n_current_artifacts_missing_architect_control"))
        == 0
        and _safe_int(summary.get("n_produced_artifact_ids_missing_from_blackboard"))
        == 0
        and _safe_int(summary.get("n_policy_mismatches")) == 0
        and _safe_int(summary.get("n_path_mismatches")) == 0
    )


def _runtime_handoff_transition_summary_scorecard_passed(
    payload: Mapping[str, Any],
    *,
    runtime_task_handoff_trace_rows: int,
    runtime_handoff_transition_manifest_present: bool,
    runtime_handoff_transition_manifest_stale: bool,
    runtime_handoff_trace_alignment_ok: bool,
    runtime_handoff_transition_summary_payload: Mapping[str, Any],
) -> bool:
    if runtime_handoff_transition_manifest_stale:
        return False
    if not runtime_handoff_trace_alignment_ok:
        return False
    if not runtime_handoff_transition_manifest_present:
        return False
    if not isinstance(runtime_handoff_transition_summary_payload, Mapping):
        return False
    required_keys = (
        "n_transition_rows",
        "n_trace_handoff_ids",
        "n_handoff_ledger_rows",
        "n_trace_handoff_ids_missing_from_ledger",
        "n_ledger_handoff_ids_missing_from_traces",
        "handoff_trace_alignment_ok",
        "n_transitions_with_acceptance_gate",
        "n_transitions_with_expected_artifacts",
        "all_transitions_have_acceptance_gate",
        "all_transitions_have_expected_artifacts",
        "trace_handoff_ids_missing_from_ledger",
        "ledger_handoff_ids_missing_from_traces",
    )
    if any(
        key not in runtime_handoff_transition_summary_payload
        for key in required_keys
    ):
        return False
    n_transition_rows = _safe_int(
        runtime_handoff_transition_summary_payload.get("n_transition_rows")
    )
    n_trace_handoff_ids = _safe_int(
        runtime_handoff_transition_summary_payload.get("n_trace_handoff_ids")
    )
    n_ledger_handoff_ids = _safe_int(
        runtime_handoff_transition_summary_payload.get("n_handoff_ledger_rows")
    )
    n_transitions_with_acceptance_gate = _safe_int(
        runtime_handoff_transition_summary_payload.get(
            "n_transitions_with_acceptance_gate"
        )
    )
    n_transitions_with_expected_artifacts = _safe_int(
        runtime_handoff_transition_summary_payload.get(
            "n_transitions_with_expected_artifacts"
        )
    )
    return bool(
        runtime_handoff_transition_summary_payload.get("handoff_trace_alignment_ok")
        is True
        and n_transition_rows == _safe_int(
            payload.get("n_runtime_handoff_transition_rows")
        )
        and n_transition_rows == runtime_task_handoff_trace_rows
        and n_trace_handoff_ids == runtime_task_handoff_trace_rows
        and n_ledger_handoff_ids
        == _safe_int(payload.get("n_runtime_task_handoff_ledger_rows"))
        and _safe_int(
            runtime_handoff_transition_summary_payload.get(
                "n_trace_handoff_ids_missing_from_ledger"
            )
        )
        == 0
        and _safe_int(
            runtime_handoff_transition_summary_payload.get(
                "n_ledger_handoff_ids_missing_from_traces"
            )
        )
        == 0
        and n_transitions_with_acceptance_gate == n_transition_rows
        and n_transitions_with_expected_artifacts == n_transition_rows
        and runtime_handoff_transition_summary_payload.get(
            "all_transitions_have_acceptance_gate"
        )
        is True
        and runtime_handoff_transition_summary_payload.get(
            "all_transitions_have_expected_artifacts"
        )
        is True
        and not runtime_handoff_transition_summary_payload.get(
            "trace_handoff_ids_missing_from_ledger"
        )
        and not runtime_handoff_transition_summary_payload.get(
            "ledger_handoff_ids_missing_from_traces"
        )
    )


def _runtime_architect_transition_policy_scorecard_passed(
    payload: Mapping[str, Any],
    *,
    architect_orchestration_executed: bool,
    runtime_task_handoff_trace_rows: int,
    runtime_handoff_transitions_aligned_with_architect_plan: int,
    runtime_handoff_transition_summary_audited: bool,
    runtime_handoff_transition_summary_payload: Mapping[str, Any],
) -> bool:
    if not architect_orchestration_executed or runtime_task_handoff_trace_rows <= 0:
        return True
    if not runtime_handoff_transition_summary_audited:
        return False
    if (
        "n_transitions_aligned_with_architect_execution_plan"
        not in runtime_handoff_transition_summary_payload
    ):
        return False
    summary_aligned = _safe_int(
        runtime_handoff_transition_summary_payload.get(
            "n_transitions_aligned_with_architect_execution_plan"
        )
    )
    summary_sources = runtime_handoff_transition_summary_payload.get(
        "route_decision_sources", {}
    )
    if not isinstance(summary_sources, Mapping):
        summary_sources = {}
    top_sources = payload.get("runtime_handoff_transition_route_sources", {})
    if not isinstance(top_sources, Mapping):
        top_sources = {}
    return bool(
        runtime_handoff_transitions_aligned_with_architect_plan == summary_aligned
        and summary_aligned > 0
        and _safe_int(summary_sources.get("architect_execution_plan")) > 0
        and _safe_int(top_sources.get("architect_execution_plan"))
        == _safe_int(summary_sources.get("architect_execution_plan"))
    )


