def _exact_semantic_typechecked_review_visible_scorecard_passed(
    *,
    primary_typechecked_review_required: bool,
    primary_typechecked_review_required_present: bool,
    primary_typechecked_review_packets: int,
    primary_materialized_typechecked_review_required: bool,
    primary_materialized_typechecked_review_required_present: bool,
    primary_materialized_typechecked_review_packets: int,
    late_typechecked_review_required: bool,
    late_materialized_typechecked_review_required_present: bool,
    late_materialized_typechecked_review_packets: int,
    late_lean_typechecked_review_required_present: bool,
    late_typechecked_review_packets: int,
    primary_typechecked_review_recheck_rows: int,
    primary_typechecked_review_verifier_gate_work_orders: int,
    primary_typechecked_review_blocked_packets: int,
    primary_typechecked_review_bridge_packets: int,
    materialized_typechecked_review_recheck_rows: int,
    materialized_typechecked_review_verifier_gate_work_orders: int,
    materialized_typechecked_review_blocked_packets: int,
    materialized_typechecked_review_bridge_packets: int,
    materialized_typechecked_review_bridge_decisions: int,
    late_typechecked_review_recheck_rows: int,
    late_typechecked_review_verifier_gate_work_orders: int,
    late_typechecked_review_blocked_packets: int,
) -> bool:
    primary_review_activity = any(
        count > 0
        for count in (
            primary_typechecked_review_packets,
            primary_typechecked_review_recheck_rows,
            primary_typechecked_review_verifier_gate_work_orders,
            primary_typechecked_review_blocked_packets,
            primary_typechecked_review_bridge_packets,
        )
    )
    primary_materialized_review_activity = any(
        count > 0
        for count in (
            primary_materialized_typechecked_review_packets,
            materialized_typechecked_review_recheck_rows,
            materialized_typechecked_review_verifier_gate_work_orders,
            materialized_typechecked_review_blocked_packets,
            materialized_typechecked_review_bridge_packets,
            materialized_typechecked_review_bridge_decisions,
        )
    )
    late_review_queue_activity = any(
        count > 0
        for count in (
            late_typechecked_review_recheck_rows,
            late_typechecked_review_verifier_gate_work_orders,
            late_typechecked_review_blocked_packets,
        )
    )
    if primary_review_activity and not primary_typechecked_review_required_present:
        return False
    if (
        primary_materialized_review_activity
        and not primary_materialized_typechecked_review_required_present
    ):
        return False
    if (
        late_materialized_typechecked_review_packets > 0
        and not late_materialized_typechecked_review_required_present
    ):
        return False
    if (
        late_typechecked_review_packets > 0
        and not late_lean_typechecked_review_required_present
    ):
        return False
    if late_review_queue_activity and not (
        late_materialized_typechecked_review_required_present
        or late_lean_typechecked_review_required_present
    ):
        return False
    if not (
        primary_typechecked_review_required
        or primary_materialized_typechecked_review_required
        or late_typechecked_review_required
    ):
        return True
    return any(
        count > 0
        for count in (
            primary_typechecked_review_recheck_rows,
            primary_typechecked_review_verifier_gate_work_orders,
            primary_typechecked_review_blocked_packets,
            primary_typechecked_review_bridge_packets,
            materialized_typechecked_review_recheck_rows,
            materialized_typechecked_review_verifier_gate_work_orders,
            materialized_typechecked_review_blocked_packets,
            materialized_typechecked_review_bridge_packets,
            materialized_typechecked_review_bridge_decisions,
            late_typechecked_review_recheck_rows,
            late_typechecked_review_verifier_gate_work_orders,
            late_typechecked_review_blocked_packets,
        )
    )


def _scorecard_row(
    requirement_id: str,
    passed: bool,
    evidence: str,
    blocker: str,
    **routing: Any,
) -> dict[str, Any]:
    scope = str(routing.pop("scope", "integrated_runtime") or "integrated_runtime")
    blocker_text = str(blocker or "").strip()
    if not passed and not blocker_text:
        blocker_text = _runtime_failed_scorecard_blocker(
            {"requirement_id": requirement_id}
        )
    row = {
        "requirement_id": requirement_id,
        "scope": scope,
        "passed": bool(passed),
        "evidence": evidence,
        "blocker": "" if passed else blocker_text,
    }
    if routing and not bool(passed):
        row.update(routing)
    return row


def _cross_task_generalization_scorecard_routing(
    payload: Mapping[str, Any],
) -> dict[str, Any]:
    first_family, second_family = cross_task_generalization_family_pair(
        payload.get("task_families", [])
    )
    command = (
        ".venv/bin/python -m ai_statistician.cli research-agent-runtime "
        f"--question-task-family {first_family} "
        f"--question-task-family {second_family} "
        "--min-task-families 2 "
        "--provider anthropic "
        "--capability-eval "
        "--capability-eval-preset full-live "
        f"--max-iterations {FULL_LIVE_RERUN_MIN_ITERATIONS} "
        "--out runs/main_worker_cross_family_full_live"
    )
    return {
        "next_owner_subsystem": "ArchitectCoordinator",
        "target_behavior": (
            "Run a live Architect-controlled capability eval over at least two "
            "explicit statistics task families, then prove full source/frontier "
            "theorems in each selected family before claiming L9 generality."
        ),
        "recommended_capability_eval_command": command,
        "success_metric": (
            "explicit target-bound task family ids>=2 and "
            "n_task_families_with_full_frontier_target_bound_kernel_verified>=2 "
            "with explicit family ids and local Lean/AXLE kernel verification "
            "for the full source/frontier theorem in each family"
        ),
        "proof_evidence_status": "CAPABILITY_SCORECARD_ROUTING_NOT_PROOF_EVIDENCE",
        "routing_boundary": (
            "This recommendation is evaluation routing metadata. It is not proof "
            "evidence and does not satisfy L9 until the audit records real "
            "kernel-verified full theorem evidence across the selected families."
        ),
    }


